#!/usr/bin/env python3
"""Update a HWPX (zip) document using JSON + CSV inputs.

Edits performed:
- Replace six field values everywhere they occur:
  customer name, current owner, renewal window, pricing band,
  escalation contact, pricing note.
- Replace the three follow-up lines using followups.csv ordered by `sequence`.
- For any paragraph modified: remove layout-cache elements (linesegarray, lineseg, etc.)
- Do NOT modify the appendix sentence paragraph: `이 부록 문단은 그대로 유지해야 합니다.`

This script is intentionally defensive about HWPX XML:
- Collect and register namespaces before parsing to preserve prefixes on output.
- Paragraph text may be split across multiple <hp:run>/<hp:t> nodes, so we operate
  on the concatenated paragraph text and then write back to the first <hp:t>.
"""

from __future__ import annotations

import csv
import os
import re
import shutil
import zipfile
from dataclasses import dataclass
from pathlib import Path
import xml.etree.ElementTree as ET


SRC_HWPX = Path("/root/renewal_playbook.hwpx")
JSON_PATH = Path("/root/renewal_update.json")
CSV_PATH = Path("/root/followups.csv")
OUT_HWPX = Path("/root/renewal_playbook_updated.hwpx")

WORK_DIR = Path("/tmp/hwpx_work/runtime")
EXTRACT_DIR = WORK_DIR / "extracted"

APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."

CACHE_LOCALNAMES = {
    # seen in this document
    "linesegarray",
    "lineseg",
    # possible variants
    "lineSegArray",
    "lineSeg",
    "linesegArray",
    "lineSegarray",
}

EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")


def localname(tag: str) -> str:
    """Return element localname for tags like '{uri}p' or 'hp:p'."""
    if tag is None:
        return ""
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    if ":" in tag:
        return tag.split(":", 1)[1]
    return tag


def collect_and_register_namespaces(xml_path: Path) -> dict[str, str]:
    """Collect namespaces using iterparse(start-ns) and register them.

    Registering namespaces before parsing helps ElementTree preserve prefixes when writing.
    """
    ns_map: dict[str, str] = {}
    for event, elem in ET.iterparse(str(xml_path), events=("start-ns",)):
        prefix, uri = elem
        # ElementTree may emit duplicates; keep first-seen mapping for a prefix.
        if prefix in ns_map and ns_map[prefix] == uri:
            continue
        ns_map[prefix] = uri

    for prefix, uri in ns_map.items():
        # ElementTree uses '' for default namespace prefix.
        ET.register_namespace(prefix or "", uri)

    return ns_map


def paragraph_t_nodes(p: ET.Element) -> list[ET.Element]:
    return [e for e in p.iter() if localname(e.tag) == "t"]


def paragraph_text(p: ET.Element) -> str:
    parts: list[str] = []
    for t in paragraph_t_nodes(p):
        if t.text:
            parts.append(t.text)
    return "".join(parts)


def set_paragraph_text(p: ET.Element, new_text: str) -> bool:
    """Set paragraph text into the existing <...:t> nodes.

    Strategy: put full new text in the first <t>, clear the rest.
    Returns True if any <t> node actually changed.
    """
    t_nodes = paragraph_t_nodes(p)
    if not t_nodes:
        return False

    old_full = paragraph_text(p)
    if old_full == new_text:
        return False

    # Assign full text to first node, clear the rest.
    t_nodes[0].text = new_text
    for t in t_nodes[1:]:
        t.text = ""
    return True


def prune_layout_cache(el: ET.Element) -> bool:
    """Remove layout-cache nodes from within element; returns True if removed any."""

    removed_any = False

    def _prune(parent: ET.Element) -> None:
        nonlocal removed_any
        for child in list(parent):
            if localname(child.tag) in CACHE_LOCALNAMES:
                parent.remove(child)
                removed_any = True
            else:
                _prune(child)

    _prune(el)
    return removed_any


@dataclass
class Updates:
    customer: str
    owner_name: str
    window_start: str
    window_end: str
    band: str
    escalation_email: str
    note: str

    @property
    def window_range(self) -> str:
        return f"{self.window_start} ~ {self.window_end}"


def load_updates() -> Updates:
    import json

    data = json.loads(JSON_PATH.read_text(encoding="utf-8"))
    return Updates(
        customer=data["customer"],
        owner_name=data["owner_name"],
        window_start=data["window_start"],
        window_end=data["window_end"],
        band=data["band"],
        escalation_email=data["escalation_email"],
        note=data["note"],
    )


def load_followups() -> list[str]:
    rows: list[tuple[int, str]] = []
    with CSV_PATH.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for r in reader:
            seq = int(r["sequence"])
            item = (r.get("item") or "").strip()
            rows.append((seq, item))

    rows.sort(key=lambda x: x[0])
    return [item for _, item in rows]


def extract_hwpx() -> None:
    if WORK_DIR.exists():
        shutil.rmtree(WORK_DIR)
    EXTRACT_DIR.mkdir(parents=True, exist_ok=True)

    with zipfile.ZipFile(SRC_HWPX, "r") as z:
        z.extractall(EXTRACT_DIR)


def discover_old_values(section_paths: list[Path]) -> dict[str, str]:
    """Discover old values from the current document content.

    Because renewal_update.json only contains the NEW values, we derive the old
    values from existing labeled paragraphs and common patterns.
    """

    found: dict[str, str] = {}

    def consider(key: str, value: str) -> None:
        if key not in found and value is not None:
            v = value.strip()
            if v:
                found[key] = v

    for pth in section_paths:
        collect_and_register_namespaces(pth)
        tree = ET.parse(str(pth))
        root = tree.getroot()
        for p in root.iter():
            if localname(p.tag) != "p":
                continue
            txt = paragraph_text(p)
            if not txt:
                continue

            if APPENDIX_SENTENCE in txt:
                continue

            if txt.startswith("고객사:"):
                consider("customer", txt.split(":", 1)[1])
            if txt.startswith("현 담당자:"):
                consider("owner_name", txt.split(":", 1)[1])
            if txt.startswith("갱신 윈도우:"):
                consider("window_range", txt.split(":", 1)[1])
            if txt.startswith("갱신 윈도우 확인:"):
                consider("window_range", txt.split(":", 1)[1])

            if txt.startswith("가격 메모:"):
                consider("note", txt.split(":", 1)[1])

            # Band: prefer a bare token like 'Standard-18M'
            if "-" in txt and re.fullmatch(r"[A-Za-z]+-\d+[A-Za-z]*", txt.strip()):
                consider("band", txt)

            # Escalation email: first email found
            m = EMAIL_RE.search(txt)
            if m:
                consider("escalation_email", m.group(0))

    return found


def build_replacements(old: dict[str, str], new: Updates) -> list[tuple[str, str]]:
    rules: list[tuple[str, str]] = []

    old_customer = old.get("customer")
    if old_customer:
        rules.append((f"고객사: {old_customer}", f"고객사: {new.customer}"))
        rules.append((old_customer, new.customer))

    old_owner = old.get("owner_name")
    if old_owner:
        rules.append((f"현 담당자: {old_owner}", f"현 담당자: {new.owner_name}"))
        rules.append((old_owner, new.owner_name))

    old_window = old.get("window_range")
    if old_window:
        old_window = old_window.strip()
        rules.append((f"갱신 윈도우: {old_window}", f"갱신 윈도우: {new.window_range}"))
        rules.append((f"갱신 윈도우 확인: {old_window}", f"갱신 윈도우 확인: {new.window_range}"))
        rules.append((old_window, new.window_range))

    old_band = old.get("band")
    if old_band:
        rules.append((old_band, new.band))

    old_email = old.get("escalation_email")
    if old_email:
        rules.append((old_email, new.escalation_email))

    old_note = old.get("note")
    if old_note:
        rules.append((f"가격 메모: {old_note}", f"가격 메모: {new.note}"))
        rules.append((old_note, new.note))

    # Also ensure these canonical line forms are set even if discovery missed.
    # (These patterns are safe because they include the Korean labels.)
    rules.append(("가격 메모:", "가격 메모:"))  # no-op anchor (keeps label untouched)

    # Deduplicate while preserving order
    seen = set()
    deduped: list[tuple[str, str]] = []
    for a, b in rules:
        if a == b:
            continue
        key = (a, b)
        if key in seen:
            continue
        seen.add(key)
        deduped.append((a, b))
    return deduped


def replace_followups_in_section(root: ET.Element, followups: list[str]) -> int:
    """Replace the three follow-up paragraphs. Returns count replaced."""
    if len(followups) != 3:
        raise SystemExit(f"Expected 3 follow-up items in CSV, got {len(followups)}")

    # Primary strategy: replace paragraphs that contain the known placeholder substring.
    candidates: list[ET.Element] = []
    for p in root.iter():
        if localname(p.tag) != "p":
            continue
        txt = paragraph_text(p)
        if not txt:
            continue
        if "old follow-up" in txt:
            candidates.append(p)

    # Fallback: numbered list under the follow-up heading.
    if len(candidates) != 3:
        candidates = []
        for p in root.iter():
            if localname(p.tag) != "p":
                continue
            txt = paragraph_text(p)
            if re.match(r"^\s*[123]\.\s+", txt):
                candidates.append(p)
        # Keep only the first 3.
        candidates = candidates[:3]

    if len(candidates) != 3:
        raise SystemExit(f"Could not uniquely identify 3 follow-up paragraphs (found {len(candidates)})")

    replaced = 0
    for i, p in enumerate(candidates, start=1):
        if APPENDIX_SENTENCE in paragraph_text(p):
            continue
        new_txt = f"{i}. {followups[i-1]}"
        changed = set_paragraph_text(p, new_txt)
        if changed:
            prune_layout_cache(p)
            replaced += 1
    return replaced


def process_section_xml(xml_path: Path, replacements: list[tuple[str, str]], followups: list[str]) -> dict[str, int]:
    collect_and_register_namespaces(xml_path)
    tree = ET.parse(str(xml_path))
    root = tree.getroot()

    modified_paras = 0
    cache_removed_paras = 0

    for p in root.iter():
        if localname(p.tag) != "p":
            continue
        txt = paragraph_text(p)
        if not txt:
            continue
        if APPENDIX_SENTENCE in txt:
            continue

        new_txt = txt
        for old, new in replacements:
            if old and old in new_txt:
                new_txt = new_txt.replace(old, new)

        # If it's a pricing memo line, enforce the exact desired memo regardless of old discovery.
        if txt.startswith("가격 메모:"):
            new_txt = f"가격 메모: {updates.note}"

        if new_txt != txt:
            if set_paragraph_text(p, new_txt):
                modified_paras += 1
                if prune_layout_cache(p):
                    cache_removed_paras += 1

    # Replace follow-ups only in sections that contain the follow-up heading.
    # This doc has them in section1.xml.
    followups_replaced = 0
    if any(paragraph_text(p).strip() == "후속 조치" for p in root.iter() if localname(p.tag) == "p"):
        followups_replaced = replace_followups_in_section(root, followups)

    tree.write(str(xml_path), encoding="UTF-8", xml_declaration=True)

    return {
        "modified_paras": modified_paras,
        "cache_removed_paras": cache_removed_paras,
        "followups_replaced": followups_replaced,
    }


def repack_hwpx(out_path: Path) -> None:
    # Build file list
    all_files: list[Path] = [p for p in EXTRACT_DIR.rglob("*") if p.is_file()]

    # Relative paths in the zip must use forward slashes.
    def arcname(p: Path) -> str:
        return p.relative_to(EXTRACT_DIR).as_posix()

    mimetype_file = EXTRACT_DIR / "mimetype"

    with zipfile.ZipFile(out_path, "w") as z:
        if mimetype_file.exists():
            z.write(mimetype_file, arcname(mimetype_file), compress_type=zipfile.ZIP_STORED)

        for p in sorted(all_files, key=lambda x: arcname(x)):
            if mimetype_file.exists() and p == mimetype_file:
                continue
            z.write(p, arcname(p), compress_type=zipfile.ZIP_DEFLATED)


if __name__ == "__main__":
    updates = load_updates()
    followups = load_followups()

    extract_hwpx()

    section_paths = sorted((EXTRACT_DIR / "Contents").glob("section*.xml"))
    if not section_paths:
        raise SystemExit("No section*.xml files found under Contents/")

    old_values = discover_old_values(section_paths)
    replacements = build_replacements(old_values, updates)

    print("Discovered old values:")
    for k in sorted(old_values):
        print(f"  - {k}: {old_values[k]}")
    print("Replacement rules (old -> new):")
    for a, b in replacements:
        print(f"  - {a!r} -> {b!r}")

    stats = {}
    for pth in section_paths:
        res = process_section_xml(pth, replacements, followups)
        stats[pth.name] = res

    print("Per-section stats:")
    for name, st in stats.items():
        print(f"  - {name}: {st}")

    repack_hwpx(OUT_HWPX)
    print(f"Wrote: {OUT_HWPX}")

