def replace_followups_in_section(root: ET.Element, followups: list[str]) -> int:
    """Replace the three follow-up paragraphs. Returns count replaced."""
    if len(followups) != 3:
        raise SystemExit(f"Expected 3 follow-up items in CSV, got {len(followups)}")

    # Primary strategy: replace paragraphs that contain the known placeholder substring.
    candidates: list[ET.Element] = []
    for p in root.iter():
        if localname(p.tag) != "p":
            continue
        txt = paragraph_text(p)
        if not txt:
            continue
        if "old follow-up" in txt:
            candidates.append(p)

    # Fallback: numbered list under the follow-up heading.
    if len(candidates) != 3:
        candidates = []
        for p in root.iter():
            if localname(p.tag) != "p":
                continue
            txt = paragraph_text(p)
            if re.match(r"^\s*[123]\.\s+", txt):
                candidates.append(p)
        # Keep only the first 3.
        candidates = candidates[:3]

    if len(candidates) != 3:
        raise SystemExit(f"Could not uniquely identify 3 follow-up paragraphs (found {len(candidates)})")

    replaced = 0
    for i, p in enumerate(candidates, start=1):
        if APPENDIX_SENTENCE in paragraph_text(p):
            continue
        new_txt = f"{i}. {followups[i-1]}"
        changed = set_paragraph_text(p, new_txt)
        if changed:
            prune_layout_cache(p)
            replaced += 1
    return replaced


